import {superWorldReport} from './super-career-ui.js';
import {availabilityPanel} from './availability-ui.js';
import {standings} from './competition.js';
import {displayDate} from './manager-calendar.js';
import {hasSandboxWorld,sandboxLabel} from './sandbox-world.js';
import {isEnglishSandbox} from './english-career.js';
import {money} from './manager-money.js';
import {managerAvailable} from './manager-career.js';
import {escapeHtml as esc,clubBadge} from './ui-kit.js';
import {managerView,nextManagerFixture,managerPrimary,managerPriorities,seasonComplete} from './manager-experience.js';
import {renderSquad,renderTransfers,renderClub,renderSeason} from './manager-tools-ui.js';
import {action,viewButton,commandButton,managerCard,managerColor} from './manager-ui-kit.js';
export {managerFormCommand} from './manager-tools-ui.js';

const label=c=>c.careerRulesVersion===2?'Super League + Super Cup · unverified preview':hasSandboxWorld(c)?sandboxLabel(c):isEnglishSandbox(c)?'Premier League sandbox':c.connected?'Connected fantasy career':'Historical fantasy career';
export function managerPrimaryButton(c,pending){const p=managerPrimary(c,pending);return action(p.label,p.action,p.id||'','primary','data-manager-primary');}

export function renderManagerCareer(c,pending=null){
 const s=managerView(c),f=nextManagerFixture(c);
 return `<div class="manager-experience" style="--club:${managerColor(c)}"><header class="mgr-header"><div class="mgr-club-identity">${clubBadge(c.name,managerColor(c))}<div><span class="eyebrow">SEASON ${c.season}${f?.date?' · '+displayDate(f.date):''}</span><h1>${esc(c.name)}</h1><span class="mgr-competition-label">${esc(label(c))}</span></div></div><div class="mgr-header-actions">${action('Careers','eu-library-open','','ghost','aria-label="Career library · switch or start another"')}${s.page!=='office'&&!s.aftermath&&!s.preparing?managerPrimaryButton(c,pending):''}</div></header><nav class="mgr-nav" aria-label="Club management">${[['office','Office'],['squad','Squad'],['transfers','Transfers'],['season','Season'],['club','Club']].map(([id,name])=>viewButton(name,'page',id,s.page===id?'primary':'ghost',`aria-current="${s.page===id?'page':'false'}"`)).join('')}</nav><div class="mgr-content" data-manager-page="${s.page}">${s.aftermath&&s.report?renderAftermath(c,s.report):({office:renderOffice,squad:renderSquad,transfers:renderTransfers,season:renderSeason,club:renderClub}[s.page]||renderOffice)(c,pending)}</div><details class="mgr-provenance sandbox-notice"><summary>${esc(label(c))} · game & data details</summary><p>${hasSandboxWorld(c)?'Fictional league with fixed membership and authored starting ownership. Transfers, negotiated loans and finances persist across seasons. Real registration and loan ownership are not fully verified.':isEnglishSandbox(c)?'Dated English player-pool snapshot. This older save retains its original ownership and financial rules.':'Historical/fantasy squads and authored football rules. Connected competitions use an original game calendar and European invitations.'} Ratings, budgets, wage requests and potential are game estimates. Published values and contracts are separately dated in player dossiers. Missing source facts remain unknown.</p><p>Live fixtures support management and, for new matches, direct play with keyboard or touch. Physical fixtures retain a replay. Fast results use the statistical model. Presentation preferences do not change results.</p></details></div>`;
}

function renderOffice(c,pending){
 if(managerView(c).message){const decision=renderDecision(c,managerView(c).message);if(decision)return viewButton('Back to office','continue')+decision;}
 const f=nextManagerFixture(c),rows=standings(c.competition),me=rows.find(t=>t.id==='user'),rank=rows.findIndex(t=>t.id==='user')+1,last=c.history.at(-1),priorities=managerPriorities(c),s=managerView(c),shown=s.allPriorities?priorities:priorities.slice(0,3);
 return `<section class="mgr-fixture" aria-label="Next fixture"><div class="mgr-stadium-art" aria-hidden="true"><i></i><i></i><i></i></div><div class="mgr-fixture-content"><span class="eyebrow highlight">${['career','manager-connected'].includes(pending?.context)?'SAVED CAREER MATCH':pending?'SEPARATE DRAFT MATCH SAVED':seasonComplete(c)?'SEASON COMPLETE':'NEXT FIXTURE'}</span><div class="mgr-fixture-teams">${clubBadge(c.name,managerColor(c))}<div><p>${f?f.homeGame?'HOME FIXTURE':'AWAY FIXTURE':'YOUR SEASON'}</p><h2>${f?'vs '+esc(f.opponent.name):'The next chapter'}</h2><span>${f?esc(f.competitionName)+' · '+(f.date?displayDate(f.date):'Matchday '+(c.competition.round+1)):'Review your results and club objectives.'}</span></div>${f?clubBadge(f.opponent.name,f.opponent.color):''}</div><div class="mgr-fixture-bottom"><span>${pending?'Your decisions are saved.':priorities.some(p=>p.kind==='urgent')?'A decision needs your attention.':'Your team is ready for the next step.'}</span>${managerPrimaryButton(c,pending)}</div></div></section><div class="mgr-status-strip career-overview"><div><span>LEAGUE</span><b>${me?.p?rank+' / '+rows.length:'Opening week'}</b></div><div><span>POINTS</span><b>${me?.pts||0}</b></div><div><span>AVAILABLE</span><b>${money(c,managerAvailable(c))}</b></div><div><span>FORM</span><b class="mgr-form">${c.history.slice(-5).map(h=>`<i class="${h.score[0]>h.score[1]?'win':h.score[0]<h.score[1]?'loss':'draw'}">${h.score[0]>h.score[1]?'W':h.score[0]<h.score[1]?'L':'D'}</i>`).join('')||'—'}</b></div></div><div class="mgr-office-grid">${managerCard('YOUR ATTENTION',priorities.length?'The decisions that matter':'Clear to play',shown.map(p=>`<article class="mgr-priority ${p.kind}"><div><span class="eyebrow">${p.kind}</span><h3>${esc(p.title)}</h3><p>${esc(p.text)}</p></div>${viewButton(p.label,p.action,p.id||'')}</article>`).join('')||'<p>No urgent decisions. Keep your current team or make a change in preparation.</p>')}${managerCard('THE SEASON STORY',last?last.score.join(' – ')+' · '+last.opponent:'A new chapter',`${last?`<p>${last.home?'Home':'Away'} · ${last.competition?esc(last.competition):'Matchday '+last.round}</p>${viewButton('View last match report','last-report')}`:'<p>Your first result will start the story here.</p>'+ (c.setup?.custom&&c.careerRulesVersion===2&&c.competition.round===0?viewButton('Plan pre-season','founder'):'')}<div class="mgr-objective"><span class="eyebrow">CLUB OBJECTIVE</span><h3>${esc(c.management.objective.name)}</h3><p>Top ${c.management.objective.rank} · board confidence ${c.trust}%</p>${viewButton('View season','page','season')}</div>`,'mgr-story')}</div>${priorities.length>3?viewButton(s.allPriorities?'Show only priorities':'View all '+priorities.length+' items','all-priorities'):''}${renderDecision(c,s.message)}${availabilityPanel(c)}${c.careerRulesVersion===2?superWorldReport(c):''}`;
}

function renderDecision(c,id){
 const x=c.management.inbox.find(x=>x.id===id&&!x.resolved);
 if(x)return managerCard('CLUB DECISION',x.title,`<p>${esc(x.text)}</p>${x.player?`${c.management.market?.version>=2?'<p>Promise two appearances in the next six fixtures: +4 morale now, then +5 if kept or −6 if missed. Explain a prospect role instead: −2 morale now, with no new appearance promise.</p>':''}`+commandButton('Agree a rotation role','resolve',x.id,'reassure')+commandButton('Explain competition','resolve',x.id,'budget'):commandButton('Acknowledge','resolve',x.id,'budget')}`);
 return id==='event'&&c.event?managerCard('DRESSING ROOM','A recovery bonus?',`<p>Spend ${money(c,18)} to improve morale and recovery, or protect the budget and accept a small morale cost.</p>${action('Back the squad · '+money(c,18),'eu-event','support','primary',c.credits<18?'disabled':'')}${action('Protect the budget','eu-event','save')}`):'';
}
function renderAftermath(c,r){return `<section class="mgr-aftermath"><div class="mgr-aftermath-score"><span class="eyebrow highlight">${r.advanced>1?r.advanced+' FIXTURES ADVANCED':'FULL-TIME'} · ${r.physical?'LIVE MATCH':'STATISTICAL RESULT'}</span><h2 tabindex="-1" data-view-focus>${esc(c.name)} <strong>${r.score.join(' – ')}</strong> ${esc(r.opponent)}</h2><p>${r.home?'Home':'Away'} · ${esc(r.competitionName||(r.competition==='cup'?'Cup':'League'))} · league position ${r.rank}${r.previousRank!==r.rank?' · previously '+r.previousRank:''}</p><p class="mgr-result-progress">${r.progress?esc(r.progress)+' · ':''}Net club cash ${r.cashDelta>=0?'+':''}${money(c,r.cashDelta)} since your last action.</p>${viewButton('Continue to office','continue','','primary')}</div><div class="mgr-aftermath-facts">${r.facts.map(f=>managerCard('WHAT CHANGED',f.title,`<p>${esc(f.text)}</p>${f.action?viewButton('Compare rotation',f.action):''}`)).join('')}</div><div class="mgr-actions">${viewButton('View league table','table')}${viewButton('Review squad','page','squad')}${r.physical?action('Replay last managed match','eu-watch-career','','ghost'):''}</div><p class="stat-foot">${r.advanced>1?'Board and table changes cover the advanced fixtures. ':''}Reports reflect recorded results and game state; they do not establish tactical causation.</p></section>`;}

